#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <immintrin.h>
#include <omp.h>

#if defined(__AVX512F__)
#define MR 12
#define NR 32
#define KC 256
#define MB (MR * 8)
#else
#define MR 6
#define NR 16
#define KC 384
#define MB (MR * 8)
#endif

#if defined(__AVX512F__)

#define DECL(r) __m512 c##r##0 = _mm512_setzero_ps(), c##r##1 = _mm512_setzero_ps();
#define ROW(r) { __m512 av = _mm512_set1_ps(a[r]); \
    c##r##0 = _mm512_fmadd_ps(av, b0, c##r##0); \
    c##r##1 = _mm512_fmadd_ps(av, b1, c##r##1); }
#define ST(r) { float *cr = c + (size_t)(r) * ldc; \
    _mm512_storeu_ps(cr, c##r##0); _mm512_storeu_ps(cr + 16, c##r##1); }
#define AD(r) { float *cr = c + (size_t)(r) * ldc; \
    _mm512_storeu_ps(cr, _mm512_add_ps(_mm512_loadu_ps(cr), c##r##0)); \
    _mm512_storeu_ps(cr + 16, _mm512_add_ps(_mm512_loadu_ps(cr + 16), c##r##1)); }
#define PF(r) { __builtin_prefetch(c + (size_t)(r) * ldc, 1, 3); \
    __builtin_prefetch(c + (size_t)(r) * ldc + 16, 1, 3); }

static void kern(int kc, const float *restrict a, const float *restrict b,
                 float *restrict c, size_t ldc, int first)
{
    DECL(0) DECL(1) DECL(2) DECL(3) DECL(4) DECL(5)
    DECL(6) DECL(7) DECL(8) DECL(9) DECL(10) DECL(11)
    PF(0) PF(1) PF(2) PF(3) PF(4) PF(5)
    PF(6) PF(7) PF(8) PF(9) PF(10) PF(11)

    #pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        __m512 b0 = _mm512_load_ps(b);
        __m512 b1 = _mm512_load_ps(b + 16);
        ROW(0) ROW(1) ROW(2) ROW(3) ROW(4) ROW(5)
        ROW(6) ROW(7) ROW(8) ROW(9) ROW(10) ROW(11)
        a += MR;
        b += NR;
    }

    if (first) {
        ST(0) ST(1) ST(2) ST(3) ST(4) ST(5)
        ST(6) ST(7) ST(8) ST(9) ST(10) ST(11)
    } else {
        AD(0) AD(1) AD(2) AD(3) AD(4) AD(5)
        AD(6) AD(7) AD(8) AD(9) AD(10) AD(11)
    }
}

#else

#define DECL(r) __m256 c##r##0 = _mm256_setzero_ps(), c##r##1 = _mm256_setzero_ps();
#define ROW(r) { __m256 av = _mm256_broadcast_ss(a + (r)); \
    c##r##0 = _mm256_fmadd_ps(av, b0, c##r##0); \
    c##r##1 = _mm256_fmadd_ps(av, b1, c##r##1); }
#define ST(r) { float *cr = c + (size_t)(r) * ldc; \
    _mm256_storeu_ps(cr, c##r##0); _mm256_storeu_ps(cr + 8, c##r##1); }
#define AD(r) { float *cr = c + (size_t)(r) * ldc; \
    _mm256_storeu_ps(cr, _mm256_add_ps(_mm256_loadu_ps(cr), c##r##0)); \
    _mm256_storeu_ps(cr + 8, _mm256_add_ps(_mm256_loadu_ps(cr + 8), c##r##1)); }
#define PF(r) { __builtin_prefetch(c + (size_t)(r) * ldc, 1, 3); \
    __builtin_prefetch(c + (size_t)(r) * ldc + 15, 1, 3); }

static void kern(int kc, const float *restrict a, const float *restrict b,
                 float *restrict c, size_t ldc, int first)
{
    DECL(0) DECL(1) DECL(2) DECL(3) DECL(4) DECL(5)
    PF(0) PF(1) PF(2) PF(3) PF(4) PF(5)

    #pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        __m256 b0 = _mm256_load_ps(b);
        __m256 b1 = _mm256_load_ps(b + 8);
        ROW(0) ROW(1) ROW(2) ROW(3) ROW(4) ROW(5)
        a += MR;
        b += NR;
    }

    if (first) {
        ST(0) ST(1) ST(2) ST(3) ST(4) ST(5)
    } else {
        AD(0) AD(1) AD(2) AD(3) AD(4) AD(5)
    }
}

#endif

static float *g_a[2] = {NULL, NULL}, *g_b[2] = {NULL, NULL};
static size_t g_acap[2] = {0, 0}, g_bcap[2] = {0, 0};
static int g_nt = 0;

static float *grow(float **p, size_t *cap, size_t need)
{
    need = (need + 63) & ~(size_t)63;
    if (need > *cap) {
        free(*p);
        *p = (float *)aligned_alloc(64, need);
        *cap = need;
    }
    return *p;
}

static long read_long2(const char *path, long *b)
{
    FILE *f = fopen(path, "r");
    if (!f) return -2;
    long a = -1;
    if (fscanf(f, "%ld", &a) != 1) a = -1;
    if (b && fscanf(f, "%ld", b) != 1) *b = -1;
    fclose(f);
    return a;
}

/* Thread count: respect cgroup CPU quota and use one thread per physical core. */
static int pick_threads(void)
{
    int nt = omp_get_max_threads();
    if (getenv("OMP_NUM_THREADS")) return nt;

    int quota = 0;
    FILE *f = fopen("/sys/fs/cgroup/cpu.max", "r");
    if (f) {
        char buf[64];
        long per = 0;
        if (fscanf(f, "%63s %ld", buf, &per) == 2 && strcmp(buf, "max") != 0) {
            long q = atol(buf);
            if (q > 0 && per > 0) quota = (int)((q + per - 1) / per);
        }
        fclose(f);
    } else {
        long q = read_long2("/sys/fs/cgroup/cpu/cpu.cfs_quota_us", NULL);
        long per = read_long2("/sys/fs/cgroup/cpu/cpu.cfs_period_us", NULL);
        if (q > 0 && per > 0) quota = (int)((q + per - 1) / per);
    }

    int smt = 1;
    f = fopen("/sys/devices/system/cpu/cpu0/topology/thread_siblings_list", "r");
    if (f) {
        char buf[128];
        if (fgets(buf, sizeof buf, f)) {
            int cnt = 1;
            for (char *p = buf; *p; p++)
                if (*p == ',') cnt++;
            if (cnt == 1 && strchr(buf, '-')) cnt = 2;
            smt = cnt;
        }
        fclose(f);
    }

    int procs = omp_get_num_procs();
    int phys = smt > 1 ? procs / smt : procs;
    if (phys < 1) phys = 1;
    if (nt > phys) nt = phys;
    if (quota > 0 && nt > quota) nt = quota;
    if (nt < 1) nt = 1;
    return nt;
}

/* In-register transpose of an 8x8 block: r[i] holds row i, becomes column i. */
static inline void tr8(__m256 *r)
{
    __m256 t0 = _mm256_unpacklo_ps(r[0], r[1]), t1 = _mm256_unpackhi_ps(r[0], r[1]);
    __m256 t2 = _mm256_unpacklo_ps(r[2], r[3]), t3 = _mm256_unpackhi_ps(r[2], r[3]);
    __m256 t4 = _mm256_unpacklo_ps(r[4], r[5]), t5 = _mm256_unpackhi_ps(r[4], r[5]);
    __m256 t6 = _mm256_unpacklo_ps(r[6], r[7]), t7 = _mm256_unpackhi_ps(r[6], r[7]);
    __m256 s0 = _mm256_shuffle_ps(t0, t2, 0x44), s1 = _mm256_shuffle_ps(t0, t2, 0xEE);
    __m256 s2 = _mm256_shuffle_ps(t1, t3, 0x44), s3 = _mm256_shuffle_ps(t1, t3, 0xEE);
    __m256 s4 = _mm256_shuffle_ps(t4, t6, 0x44), s5 = _mm256_shuffle_ps(t4, t6, 0xEE);
    __m256 s6 = _mm256_shuffle_ps(t5, t7, 0x44), s7 = _mm256_shuffle_ps(t5, t7, 0xEE);
    r[0] = _mm256_permute2f128_ps(s0, s4, 0x20);
    r[1] = _mm256_permute2f128_ps(s1, s5, 0x20);
    r[2] = _mm256_permute2f128_ps(s2, s6, 0x20);
    r[3] = _mm256_permute2f128_ps(s3, s7, 0x20);
    r[4] = _mm256_permute2f128_ps(s0, s4, 0x31);
    r[5] = _mm256_permute2f128_ps(s1, s5, 0x31);
    r[6] = _mm256_permute2f128_ps(s2, s6, 0x31);
    r[7] = _mm256_permute2f128_ps(s3, s7, 0x31);
}

/* B panel p of slice [k0, k0+kc): columns [p*NR, p*NR+NR), k-major, zero padded. */
static void pack_b_panel(const float *B, int n, int p, int k0, int kc, float *dst)
{
    int j0 = p * NR;
    int w = n - j0 < NR ? n - j0 : NR;
    const float *src = B + (size_t)k0 * n + j0;
    if (w == NR) {
        for (int k = 0; k < kc; k++) {
            memcpy(dst, src, NR * sizeof(float));
            src += n;
            dst += NR;
        }
    } else {
        for (int k = 0; k < kc; k++) {
            int j = 0;
            for (; j < w; j++) dst[j] = src[j];
            for (; j < NR; j++) dst[j] = 0.0f;
            src += n;
            dst += NR;
        }
    }
}

/* A strip s of slice [k0, k0+kc): rows [s*MR, s*MR+MR), k-major, zero padded.
   Loads 8 consecutive k per row and transposes in registers. */
static void pack_a_strip(const float *A, int n, int s, int k0, int kc, float *d)
{
    int i0 = s * MR;
    int h = n - i0 < MR ? n - i0 : MR;
    int k = 0;
    if (h == MR) {
        const float *rows[MR];
        for (int r = 0; r < MR; r++) rows[r] = A + (size_t)(i0 + r) * n + k0;
        for (; k + 8 <= kc; k += 8) {
            __m256 x[8];
#if MR == 12
            __m256 y[8];
            for (int r = 0; r < 8; r++) x[r] = _mm256_loadu_ps(rows[r] + k);
            for (int r = 0; r < 8; r++) y[r] = _mm256_loadu_ps(rows[8 + (r < 4 ? r : 0)] + k);
            tr8(x);
            tr8(y);
            for (int kk = 0; kk < 8; kk++) {
                float *dd = d + (size_t)(k + kk) * MR;
                _mm256_storeu_ps(dd, x[kk]);
                _mm_storeu_ps(dd + 8, _mm256_castps256_ps128(y[kk]));
            }
#else
            for (int r = 0; r < 8; r++) x[r] = _mm256_loadu_ps(rows[r < MR ? r : 0] + k);
            tr8(x);
            for (int kk = 0; kk < 8; kk++) {
                float *dd = d + (size_t)(k + kk) * MR;
                _mm_storeu_ps(dd, _mm256_castps256_ps128(x[kk]));
                _mm_storel_pi((__m64 *)(dd + 4), _mm256_extractf128_ps(x[kk], 1));
            }
#endif
        }
    }
    for (; k < kc; k++) {
        float *dd = d + (size_t)k * MR;
        for (int r = 0; r < MR; r++)
            dd[r] = r < h ? A[(size_t)(i0 + r) * n + k0 + k] : 0.0f;
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    if (!g_nt) g_nt = pick_threads();

    int nk = (n + KC - 1) / KC;
    int kcb = (n + nk - 1) / nk;

    int nstrips = (n + MR - 1) / MR;
    int npanels = (n + NR - 1) / NR;
    size_t astride = (size_t)MR * kcb;
    size_t bstride = (size_t)NR * kcb;

    float *Ab[2], *Bb[2];
    for (int q = 0; q < 2; q++) {
        Ab[q] = grow(&g_a[q], &g_acap[q], (size_t)nstrips * astride * sizeof(float));
        Bb[q] = grow(&g_b[q], &g_bcap[q], (size_t)npanels * bstride * sizeof(float));
    }

    int mblocks = (n + MB - 1) / MB;
    int nb = 256;
    while (nb > 2 * NR && mblocks * ((n + nb - 1) / nb) < 4 * g_nt) nb /= 2;
    int nblocks = (n + nb - 1) / nb;
    int ntasks = mblocks * nblocks;
    int npack = npanels + nstrips;

    /* Phase s packs K-slice s and computes K-slice s-1 (double buffered). */
    #pragma omp parallel num_threads(g_nt)
    for (int s = 0; s <= nk; s++) {
        int npk = s < nk ? npack : 0;
        int ncomp = s > 0 ? ntasks : 0;

        #pragma omp for schedule(dynamic, 1)
        for (int it = 0; it < npk + ncomp; it++) {
            if (it < npk) {
                int k0 = s * kcb;
                int kc = n - k0 < kcb ? n - k0 : kcb;
                int q = s & 1;
                if (it < npanels)
                    pack_b_panel(B, n, it, k0, kc, Bb[q] + (size_t)it * bstride);
                else {
                    int st = it - npanels;
                    pack_a_strip(A, n, st, k0, kc, Ab[q] + (size_t)st * astride);
                }
                continue;
            }

            int t = it - npk;
            int sl = s - 1;
            int k0 = sl * kcb;
            int kc = n - k0 < kcb ? n - k0 : kcb;
            int first = (sl == 0);
            const float *Ap = Ab[sl & 1];
            const float *Bp = Bb[sl & 1];

            int ib = t / nblocks, jb = t % nblocks;
            int i0 = ib * MB;
            int iend = i0 + MB < n ? i0 + MB : n;
            int jstart = jb * nb;
            int jend = jstart + nb < n ? jstart + nb : n;

            for (int j = jstart; j < jend; j += NR) {
                const float *bp = Bp + (size_t)(j / NR) * bstride;
                int nr = n - j < NR ? n - j : NR;
                for (int i = i0; i < iend; i += MR) {
                    const float *ap = Ap + (size_t)(i / MR) * astride;
                    int mr = n - i < MR ? n - i : MR;
                    float *cp = C + (size_t)i * n + j;
                    if (mr == MR && nr == NR) {
                        kern(kc, ap, bp, cp, (size_t)n, first);
                    } else {
                        float tmp[MR * NR] __attribute__((aligned(64)));
                        kern(kc, ap, bp, tmp, NR, 1);
                        for (int r = 0; r < mr; r++) {
                            float *cr = cp + (size_t)r * n;
                            const float *tr = tmp + r * NR;
                            if (first)
                                for (int jj = 0; jj < nr; jj++) cr[jj] = tr[jj];
                            else
                                for (int jj = 0; jj < nr; jj++) cr[jj] += tr[jj];
                        }
                    }
                }
            }
        }
    }
}
